-- The journal's data version (performance pass). Rollback: db/rollback/053_data_version.sql.
--
-- One number that moves whenever the journal's data changes, read in one query, so the Stats
-- engine (db/statsEngine) and other heavy reads can keep their results until it moves
-- (db/dataVersion.ts). Bumped by triggers on every table the numbers read; left out: app_time
-- (written each minute), insights (the engine's own ledger), notifications and the bookkeeping
-- tables. A table added later needs its three triggers (tests/data-version.test.mts checks).
CREATE TABLE data_version (id INTEGER PRIMARY KEY CHECK (id = 1), v INTEGER NOT NULL);
INSERT INTO data_version (id, v) VALUES (1, 1);
CREATE TRIGGER dv_app_settings_insert AFTER INSERT ON app_settings BEGIN UPDATE data_version SET v = v + 1 WHERE id = 1; END;
CREATE TRIGGER dv_app_settings_update AFTER UPDATE ON app_settings BEGIN UPDATE data_version SET v = v + 1 WHERE id = 1; END;
CREATE TRIGGER dv_app_settings_delete AFTER DELETE ON app_settings BEGIN UPDATE data_version SET v = v + 1 WHERE id = 1; END;
